DROP TABLE IF EXISTS `Admin_Content`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Admin_Content` (
  `ADMIN_CONTENT_ID` int NOT NULL AUTO_INCREMENT COMMENT '관리자 콘텐츠 고유번호',
  `USER_NO` bigint DEFAULT NULL COMMENT '사용자 고유 번호',
  `CONTENT_TYPE` varchar(20) NOT NULL COMMENT '콘텐츠 종류 (공지사항: NOTICE, 이용가이드: GUIDE, 인솔자: ESCORT)',
  `TITLE` varchar(255) NOT NULL COMMENT '제목',
  `CONTENT` text NOT NULL COMMENT '내용',
  `AUTHOR` varchar(10) DEFAULT NULL COMMENT '작성자 (관리자 ID 등)',
  `CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록일',
  `UPDATED_AT` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정일',
  `IS_ACTIVE` varchar(2) NOT NULL DEFAULT 'Y' COMMENT '활성 상태 (Y: 활성, N: 비활성)',
  `fixed` varchar(2) DEFAULT 'N' COMMENT '공지사항 고정',
  PRIMARY KEY (`ADMIN_CONTENT_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='관리자 전용 콘텐츠 관리 테이블';
