INSERT INTO `Admin_Content` VALUES (1,NULL,'NOTICE','[중요] 추천인 입력 관련 안내','<p>회원가입 시 <strong>추천인 아이디 입력 관련 중요 안내드립니다.</strong></p><h3>⚠️ 추천인은 가입 시에만 입력 가능합니다</h3><p>회원가입 과정에서 추천인을 입력하지 않을 경우<br>👉 <strong>가입 완료 이후에는 추천인 등록 및 수정이 불가능합니다.</strong></p><h3>🚨 꼭 확인해주세요</h3><ul><li data-list-item-id=\"edfc701bd07ac6799678bfab98beb5c4e\">추천인 입력은 <strong>회원가입 시 1회만 가능</strong></li><li data-list-item-id=\"e34332e0b32d344232de64134aa1195ac\">가입 완료 후 <strong>추가 입력 / 변경 절대 불가</strong></li><li data-list-item-id=\"e6535fdad6c3369d1da9deda0f3865be4\">추천인 미입력 시 <strong>추천인 포인트 혜택 적용 불가</strong></li></ul><h3>💡 추천인 혜택 안내</h3><p>추천인을 입력하면<br>👉 추천인에게 포인트가 지급되는 시스템이 적용됩니다.</p><p>(※ 자세한 내용은 FAQ 참고)</p><h3>📌 안내 말씀</h3><p>추천인 입력은 선택 사항이지만,<br>👉 가입 후에는 절대 추가할 수 없으니<br>가입 시 반드시 확인 후 진행해주시기 바랍니다.</p>','admin','2026-02-07 11:59:21','2026-04-13 13:50:29','Y','on'),(2,3,'LEADER','유석현','<figure class=\"table\"><table style=\"border-color:hsl(0, 0%, 0%);border-style:solid;\"><tbody><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><figure class=\"image\"><img src=\"/admin/images/746dbb85-658e-47f7-a194-9c99bc7e0f97.webp\"></figure></td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table></figure>','Admin','2026-02-21 07:18:32','2026-02-28 16:03:01','Y','N'),(3,2,'LEADER','','<figure class=\"image\"><img style=\"aspect-ratio:640/905;\" src=\"/admin/images/c2170e3f-a01f-493a-8530-b5807dd74762.jpeg\" width=\"640\" height=\"905\"></figure>','Admin','2026-02-23 12:25:06','2026-02-23 12:25:06','Y','N'),(4,NULL,'FAQ','FAQ 테스트','<p>&nbsp;테스트</p>','Admin','2026-03-14 07:51:34','2026-04-10 03:53:38','N','N'),(5,NULL,'USE_GUIDE','행집 이용가이드 필독!','<figure class=\"image\"><img style=\"aspect-ratio:1792/11024;\" src=\"/admin/images/5ea4e8e9-600a-464c-8da3-042b600aa426.jpeg\" width=\"1792\" height=\"11024\"></figure>','Admin','2026-04-09 08:24:57','2026-05-07 11:35:44','Y','N'),(6,NULL,'FAQ','[플랫폼 이용] 행집은 어떤 플랫폼인가요?','<p>행집은 공연, 행사, 축제에 필요한 인력 등을 모집하는 전문 플랫폼입니다.<br>복잡한 지원 절차 없이 원하는 행사에 <strong>간편하게 지원하고 바로 참여할 수 있는 구조</strong>입니다.</p>','Admin','2026-04-10 03:53:33','2026-04-10 03:53:33','Y','N'),(7,NULL,'FAQ','[플랫폼 이용] 다른 알바앱이랑 뭐가 다른가요?','<p>행집은 단순 구인사이트가 아니라<br>👉 실제 운영되는 행사만 등록되는 “직접 운영형 플랫폼”입니다.<br>불필요한 지원 경쟁 없이 <strong>실제 투입 가능한 인원만 선발</strong>됩니다.</p>','Admin','2026-04-10 03:55:59','2026-04-10 03:55:59','Y','N'),(8,NULL,'FAQ','[플랫폼 이용] 지원은 어떻게 하나요?','<p>로그인 후 정보등록!!</p><p>마음에 드는 캠페인 선택 → <strong>[신청하기] 버튼 클릭</strong>이면 끝입니다.<br>별도의 이력서 제출 없이 빠르게 지원 가능합니다.</p>','Admin','2026-04-13 12:24:21','2026-04-13 12:24:21','Y','N'),(9,NULL,'FAQ','[플랫폼 이용] 지원하면 무조건 되는 건가요?','<p>아닙니다.<br>행사별 인원 제한이 있어 <strong>선발 과정을 통해 확정됩니다.</strong></p>','Admin','2026-04-13 12:24:44','2026-04-13 12:24:44','Y','N'),(10,NULL,'FAQ','[플랫폼 이용] 합격 여부는 어떻게 확인하나요?','<p>합격자에 한해 <strong>개별 안내(문자 또는 카톡)</strong>가 진행됩니다.</p>','Admin','2026-04-13 12:25:21','2026-04-13 12:25:21','Y','N'),(11,NULL,'FAQ','[회원 / 권한 시스템] 회원은 어떻게 구분되나요?','<p>행집은 3단계 구조로 운영됩니다.</p><h3>유저</h3><p>👉 회원가입 후 기본 정보 입력 시 자동 부여<br>✔ 진행 캠페인 지원 가능</p><h3>경호</h3><p>👉 신분증 + 이수증 등록 후 승인 시 부여<br>✔ 진행 캠페인 + 경호 캠페인 지원 가능</p><h3>수행</h3><p>👉 현장 평가 후 인솔자 승인 시 부여<br>✔ 진행 + 경호 + 수행 캠페인 모두 지원 가능</p>','Admin','2026-04-13 13:11:16','2026-04-13 13:11:16','Y','N'),(12,NULL,'FAQ','[회원 / 권한 시스템] 수행요원은 어떻게 올라가나요?','<p>참여 횟수, 현장 수행 능력, 신뢰도를 기준으로<br>👉 관리자의 판단 및 인솔자 승인으로 상승합니다.</p>','Admin','2026-04-13 13:16:10','2026-04-13 13:16:10','Y','N'),(13,NULL,'FAQ','[지원 / 선발] 선발 기준은 무엇인가요?','<p>✔ 지원 순서<br>✔ 참여 이력<br>✔ 신뢰도<br>✔ 현장 평가</p><p>👉 성실하게 참여할수록 선발 확률이 높아집니다.</p>','Admin','2026-04-13 13:16:35','2026-04-13 13:17:02','Y','N'),(14,NULL,'FAQ','[지원 / 선발] 경력이 없어도 가능한가요?','<p>가능합니다.<br>각 캠페인에 인솔자, 경력자가 참여 하여 행집만의 교육 가이드가 따로 구성되어 있습니다.</p>','Admin','2026-04-13 13:20:29','2026-04-13 13:20:29','Y','N'),(15,NULL,'FAQ','[급여 / 정산] 급여는 언제 지급되나요?','<p>이번 달 근무 포인트 기준<br><strong>익월 말일 일괄 지급</strong>됩니다.</p>','Admin','2026-04-13 13:21:29','2026-04-13 13:21:29','Y','N'),(16,NULL,'FAQ','[급여 / 정산] 어떤 방식으로 지급되나요?','<p>등록된 계좌로 자동 지급됩니다.</p>','Admin','2026-04-13 13:23:07','2026-04-13 13:23:07','Y','N'),(17,NULL,'FAQ','[급여 / 정산] 일당제인가요?','<p>기본적으로 <strong>포인트 기반 정산 시스템</strong>입니다.<br>(포인트 → 현금 지급)</p>','Admin','2026-04-13 13:23:30','2026-04-13 13:23:30','Y','N'),(18,NULL,'FAQ','[포인트 시스템] 행집은 총 4가지 포인트 구조로 운영됩니다.','<h3>1️⃣ 출근 포인트</h3><p>👉 캠페인 정상 출석 + 퇴근 완료 시 지급<br>✔ 캠페인별 지정 포인트 지급</p><h3>2️⃣ 만근 포인트</h3><p>👉 무단결근 / 무단지각(3회) 없이 완료 시 지급</p><p>✔ 별도 정해진 근무횟수 조건 없이 캠페인 참여만 정상 수행하면 지급<br>✔ 사유 있을 경우 증빙 시 무단 처리 제외</p><h3>3️⃣ 추천인 포인트</h3><p>👉 내가 추천한 유저가 출석 + 완료 시</p><p>✔ <strong>1명당 5,000P 지급</strong><br>✔ 인원 제한 없이 무제한 가능</p><p>🚨 단,<br>👉 3개월 동안 활동 없으면 추천인 초기화<br>👉 관리자 인증 시 유지 가능</p><h3>4️⃣ 인솔자 포인트</h3><p>👉 인솔자로 지정된 경우</p><p>✔ 현장 인원 1명당 추가 포인트 지급<br>✔ 인원 많을수록 수익 증가 구조</p>','Admin','2026-04-13 13:25:14','2026-04-13 13:25:14','Y','N'),(19,NULL,'FAQ','[근무 / 현장] 어떤 일을 하나요?','<p>✔ 행사 안전 관리<br>✔ 출입 통제<br>✔ 관객 안내<br>✔ 진행 보조<br>✔ 행사에 관련된 업무</p>','Admin','2026-04-13 13:31:11','2026-04-13 13:31:11','Y','N'),(20,NULL,'FAQ','[근무지 / 행사] 지역은 어디인가요?','<p>전국 단위로 진행됩니다.</p>','Admin','2026-04-13 13:31:29','2026-04-13 13:31:29','Y','N'),(21,NULL,'FAQ','[규정 / 패널티] 지원 후 취소하면 어떻게 되나요?','<p>사전 취소는 담당자와 소통하여 가능하나 반복 시 선발 제한됩니다.</p>','Admin','2026-04-13 13:40:46','2026-04-13 13:40:46','Y','N'),(22,NULL,'FAQ','[규정 / 패널티] 무단 불참 시 어떻게 되나요?','<p>패널티 및 향후 참여 제한이 적용됩니다.</p>','Admin','2026-04-13 13:41:08','2026-04-13 13:41:08','Y','N'),(23,NULL,'FAQ','[프로필 관련] 프로필 사진은 왜 등록해야 하나요?','<p>👉 관리자 확인용입니다.<br>✔ 다른 유저에게는 공개되지 않습니다.<br>✔ 반드시 등록해야 정상 이용 가능합니다.</p>','Admin','2026-04-13 13:41:33','2026-04-13 13:41:33','Y','N'),(24,NULL,'FAQ','[기타] 계속 참여할 수 있나요?','<p>👉 가능합니다.<br>성실 참여 시 더 많은 기회 제공됩니다.</p>','Admin','2026-04-13 13:41:59','2026-04-13 13:41:59','Y','N');
/*!40000 ALTER TABLE `Admin_Content` ENABLE KEYS */;
UNLOCK TABLES;

