DROP TABLE IF EXISTS `campaign`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `campaign` (
  `CAMPAIGN_ID` bigint NOT NULL AUTO_INCREMENT COMMENT '캠페인 고유 ID',
  `CAMPAIGN_TITLE` varchar(100) NOT NULL COMMENT '캠페인명',
  `CAMPAIGN_PAY` int DEFAULT '0' COMMENT '캠페인 급여',
  `TIME_SEGMENT` varchar(10) DEFAULT NULL COMMENT '주간/야간 체크',
  `WORK_HOUR` varchar(2) DEFAULT NULL COMMENT '하루근무 시간',
  `WAGE_CHK` varchar(2) DEFAULT NULL COMMENT '일급시급 체크',
  `PAY` int DEFAULT '0' COMMENT '급여',
  `COMPANY_NM` varchar(100) NOT NULL COMMENT '업체명',
  `COMPANY_PH` varchar(20) NOT NULL COMMENT '업체 대표 연락처',
  `TYPE_CODE` varchar(2) DEFAULT '0' COMMENT '보안 유형 코드 (FK 예정)',
  `STATUS_CODE` varchar(2) DEFAULT '0' COMMENT '캠페인 상태 코드 (FK 예정)',
  `RECRUITMENT_NUM` int DEFAULT NULL COMMENT '모집 인원 수',
  `APPLICANTS_NUM` int DEFAULT '0' COMMENT '신청자 수',
  `FILE_ID` bigint DEFAULT NULL COMMENT '첨부 파일 ID',
  `PLACE_ADDR` varchar(255) DEFAULT NULL COMMENT '장소 주소',
  `MISSION` text COMMENT '캠페인 안내 사항',
  `LEADER_CODE` varchar(2) NOT NULL COMMENT '인솔자 코드',
  `LEADER_PAY` int DEFAULT '0' COMMENT '인솔자 급여',
  `LEADER_POINT` int DEFAULT '0' COMMENT '인솔자 포인트',
  `APP_PERIOD_STR` datetime DEFAULT NULL COMMENT '신청 기간 시작',
  `APP_PERIOD_END` datetime DEFAULT NULL COMMENT '신청 기간 종료',
  `EVENT_PERIOD_STR` datetime DEFAULT NULL COMMENT '행사 기간 시작',
  `EVENT_PERIOD_END` datetime DEFAULT NULL COMMENT '행사 기간 종료',
  `RESULT_DATE` datetime DEFAULT NULL COMMENT '명단 발표 기간',
  `CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `UPDATED_AT` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '최종 수정 일시',
  `IS_ACTIVE` varchar(2) DEFAULT 'Y' COMMENT '활성화 여부 (Y/N)',
  `IS_DELETED` varchar(2) DEFAULT 'N' COMMENT '삭제 여부 (Y/N)',
  PRIMARY KEY (`CAMPAIGN_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='캠페인 정보 테이블';
/*!40101 SET character_set_client = @saved_cs_client */;

