--
-- Table structure for table `common_codes`
--

DROP TABLE IF EXISTS `common_codes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `common_codes` (
  `CODE_ID` bigint NOT NULL AUTO_INCREMENT COMMENT '코드 정의 고유 ID',
  `CODE_GROUP` varchar(50) NOT NULL COMMENT '코드 그룹 (예: CAMPAIGN_STATUS)',
  `CODE` varchar(50) NOT NULL COMMENT '코드 번호 (예: 01)',
  `CODE_NAME` varchar(255) NOT NULL COMMENT '코드 명칭 (예: 등록 대기)',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '추가 설명',
  `SORT_ORDER` int NOT NULL DEFAULT '1' COMMENT '코드 표시 순서',
  `IS_DELETE` char(2) NOT NULL DEFAULT 'N' COMMENT '사용 여부 (Y/N)',
  `CREATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `UPDATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '최종 수정 일시',
  PRIMARY KEY (`CODE_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='공통 코드 관리 테이블';
