--
-- Table structure for table `files`
--

DROP TABLE IF EXISTS `files`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `files` (
  `FILE_ID` bigint NOT NULL AUTO_INCREMENT COMMENT '파일 고유 식별자',
  `FILE_TYPE` varchar(50) NOT NULL COMMENT '파일 용도 구분자 (PROFILE_IMG, BOARD_ATTACH 등)',
  `TARGET_ID` bigint DEFAULT NULL COMMENT '대상 ID (예: 게시글 ID, 회원 ID)',
  `TARGET_TYPE` varchar(50) DEFAULT NULL COMMENT '대상 테이블명 (예: USER, BOARD)',
  `ORIGINAL_NAME` varchar(255) NOT NULL COMMENT '원본 파일명',
  `SAVED_NAME` varchar(255) NOT NULL COMMENT '서버 저장 파일명 (UUID)',
  `FILE_PATH` varchar(500) NOT NULL COMMENT '파일 저장 경로',
  `FILE_SIZE` bigint NOT NULL COMMENT '파일 크기 (바이트)',
  `FILE_EXTENSION` varchar(10) DEFAULT NULL COMMENT '확장자',
  `MIME_TYPE` varchar(100) DEFAULT NULL COMMENT 'MIME 타입',
  `DOWNLOAD_COUNT` int DEFAULT '0' COMMENT '다운로드 횟수',
  `IS_DELETED` varchar(2) NOT NULL DEFAULT 'N' COMMENT '삭제 여부 (Y/N)',
  `CREATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `CREATED_BY` bigint DEFAULT NULL COMMENT '파일 업로드 사용자 ID',
  `UPDATED_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '최종 수정 일시',
  `UPDATED_BY` bigint DEFAULT NULL COMMENT '파일 수정 사용자 ID',
  PRIMARY KEY (`FILE_ID`),
  KEY `IDX_FILE_LOOKUP` (`FILE_TYPE`,`TARGET_TYPE`,`TARGET_ID`,`IS_DELETED`)
) ENGINE=InnoDB AUTO_INCREMENT=326 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='파일 관리 테이블';
/*!40101 SET character_set_client = @saved_cs_client */;

