--
-- Table structure for table `inquiry`
--

DROP TABLE IF EXISTS `inquiry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inquiry` (
  `inquiry_id` bigint NOT NULL AUTO_INCREMENT COMMENT '문 Id',
  `company_nm` varchar(255) DEFAULT NULL COMMENT '업체명',
  `user_id` varchar(50) DEFAULT NULL COMMENT '작성자Id',
  `user_nm` varchar(50) DEFAULT NULL COMMENT '작성자',
  `phone_num` varchar(255) DEFAULT NULL COMMENT '폰넘버',
  `title` varchar(255) DEFAULT NULL COMMENT '제목',
  `content` longtext COMMENT '내용',
  `salary` int DEFAULT NULL COMMENT '단가',
  `pay_date` datetime DEFAULT NULL COMMENT '결제일',
  `costume` varchar(255) DEFAULT NULL COMMENT '메모',
  `gathering_time` varchar(255) DEFAULT NULL COMMENT '집결시간',
  `inquiry_type` varchar(30) DEFAULT NULL COMMENT '타입',
  `campaign_title` varchar(50) DEFAULT NULL COMMENT '캠페인제목',
  `agree` varchar(2) DEFAULT NULL COMMENT '동의유무',
  `agree_opt` varchar(2) DEFAULT NULL,
  `address` varchar(100) DEFAULT NULL COMMENT '주소',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록일',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '수정일',
  `is_deleted` varchar(1) DEFAULT 'N' COMMENT '사용 여부 (Y/N)',
  PRIMARY KEY (`inquiry_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

