/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `phone_auth` (
  `ID` bigint NOT NULL AUTO_INCREMENT COMMENT '고유 식별자, 자동 증가하는 기본키',
  `phone_number` varchar(255) DEFAULT NULL,
  `auth_code` varchar(255) DEFAULT NULL,
  `CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '인증번호 생성 시각, 기본값은 현재 시간',
  `EXPIRES_AT` datetime NOT NULL COMMENT '인증번호 만료 시각, 반드시 지정해야 함',
  `USED` tinyint(1) DEFAULT '0' COMMENT '인증번호 사용 여부(기본값 FALSE, 사용 시 TRUE로 변경)',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

