--
-- Table structure for table `point_history`
--

DROP TABLE IF EXISTS `point_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `point_history` (
  `point_id` bigint NOT NULL AUTO_INCREMENT COMMENT '포인트 고유 번호',
  `user_id` bigint NOT NULL COMMENT '유저 번호 (FK)',
  `amount` int NOT NULL DEFAULT '0' COMMENT '변동 포인트 금액',
  `point_type` varchar(20) NOT NULL COMMENT '구분 (EARN: 적립, CANCEL: 취소)',
  `category` varchar(30) NOT NULL COMMENT '종류 (WORK, REFERRAL, FULL_ATTEND, LEADER)',
  `reason_info` varchar(255) DEFAULT NULL COMMENT '특이사항 사유',
  `source_id` bigint DEFAULT NULL COMMENT '참조 ID (개별 기록)',
  `campaign_id` bigint DEFAULT NULL COMMENT '캠페인 ID (그룹)',
  `mission_date` date DEFAULT NULL COMMENT '실제 일한 날짜',
  `settlement_status` varchar(20) DEFAULT 'READY' COMMENT '정산 상태 (READY: 대기, COMPLETED: 완료)',
  `after_balance` int DEFAULT NULL COMMENT '해당 건 처리 후 유저의 총 잔액',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `is_deleted` char(1) DEFAULT 'N' COMMENT '삭제 여부 (Y/N)',
  PRIMARY KEY (`point_id`)
) ENGINE=InnoDB AUTO_INCREMENT=657 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `point_history`
--

