--
-- Table structure for table `point_settlement`
--

DROP TABLE IF EXISTS `point_settlement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `point_settlement` (
  `settlement_id` bigint NOT NULL AUTO_INCREMENT COMMENT '정산 ID',
  `user_id` varchar(50) NOT NULL COMMENT '사용자 ID',
  `target_month` varchar(7) NOT NULL COMMENT '정산 대상 월 (YYYY-MM)',
  `total_work_amount` int DEFAULT '0' COMMENT '업무 포인트 합계',
  `total_leader_amount` int DEFAULT '0' COMMENT '리더 추가 포인트 합계',
