  `PASSWORD` varchar(255) NOT NULL COMMENT '암호화된 비밀번호',
  `account_number` varchar(100) DEFAULT NULL COMMENT '계좌번호',
  `BANK_NM` varchar(50) DEFAULT NULL COMMENT '은행명',
  `depositor` varchar(100) DEFAULT NULL COMMENT '예금주명',
  `EMAIL` varchar(80) NOT NULL COMMENT '이메일 주소',
  `NICKNAME` varchar(80) DEFAULT NULL COMMENT '닉네임',
  `phone_num` varchar(100) DEFAULT NULL COMMENT '전화번호',
  `POINT_ID` int NOT NULL DEFAULT '0' COMMENT '포인트 ID',
  `COMMON_ID` varchar(2) DEFAULT NULL COMMENT '공통코드 ID',
  `ADDRESS_ID` varchar(5) DEFAULT NULL COMMENT '주소 ID',
  `AUTH_ID` varchar(50) DEFAULT NULL COMMENT '권한 ID',
  `STOP_DATE` date DEFAULT NULL COMMENT '이용 정지 일자',
  `MEMO` text COMMENT '메모',
  `FILE_ID` varchar(255) DEFAULT NULL COMMENT '첨부 파일 ID',
  `ROLE` varchar(10) DEFAULT 'USER' COMMENT '사용자 역할',
  `PAY` int DEFAULT '0' COMMENT '지급 포인트',
  `REFERRER_NO` bigint DEFAULT NULL COMMENT '추천인 번호',
  `REFERRER_ID` varchar(50) DEFAULT NULL COMMENT '추천인 아이디',
  `GUARD_TYPE` varchar(2) DEFAULT NULL COMMENT '경호 유형',
  `POINT_FULL` int DEFAULT '0' COMMENT '총 포인트',
  `CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `UPDATED_AT` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정 일시',
  `IS_DELETED` varchar(2) NOT NULL DEFAULT 'N' COMMENT '삭제 여부 (Y/N)',
  `IS_STOPPED` varchar(2) NOT NULL DEFAULT 'N' COMMENT '정지 여부 (Y/N)',
  `ENABLED` varchar(2) NOT NULL DEFAULT '1' COMMENT '계정 활성화 여부 (1=활성, 0=비활성)',
  `phone_hash` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `idx_phone_hash` (`phone_hash`)
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='사용자 계정 정보 테이블';
