--
-- Table structure for table `user_address`
--

DROP TABLE IF EXISTS `user_address`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_address` (
  `ADDRESS_ID` int NOT NULL AUTO_INCREMENT COMMENT '주소 고유 번호',
  `USER_ID` int NOT NULL COMMENT '주소 소유자 사용자 ID',
  `ZONE_CODE` varchar(5) NOT NULL COMMENT '우편번호 (예: 06130)',
  `PROVINCE` varchar(50) NOT NULL COMMENT '시/도 명 (예: 서울특별시)',
  `CITY` varchar(50) NOT NULL COMMENT '시/군/구 명 (예: 강남구)',
  `ROAD_NAME` varchar(100) DEFAULT NULL COMMENT '도로명 (예: 테헤란로)',
  `road_address` varchar(500) DEFAULT NULL COMMENT '상세 주소 (예: 101동 203호)',
  `JIBUN_ADDRESS` varchar(100) DEFAULT NULL COMMENT '지번 주소',
  `EXTRA_ADDRESS` varchar(100) NOT NULL COMMENT '참고항목 (예: 역삼동)',
  `DETAIL_ADDRESS` varchar(255) DEFAULT NULL COMMENT '상세 주소 (예: 101동 203호)',
  `full_address` varchar(500) DEFAULT NULL COMMENT '전체 주소 (예: 디지털로33길 28 601)',
  `IS_DEFAULT` tinyint(1) DEFAULT '0' COMMENT '대표 주소 여부',
  `IS_DELETED` varchar(2) DEFAULT 'N' COMMENT '삭제 여부 (Y/N)',
  `CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `UPDATED_AT` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '최종 수정 일시',
  PRIMARY KEY (`ADDRESS_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='사용자 주소 정보 테이블';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user_address`
--

