  `STATUS` varchar(2) DEFAULT '0' COMMENT '상태 코드',
  `EXTEND_PERIOD` int DEFAULT NULL COMMENT '연장 기간 (일)',
  `APPLIED_STR_DATE` datetime DEFAULT NULL COMMENT '캠페인 행사 시작일',
  `APPLIED_END_DATE` datetime DEFAULT NULL COMMENT '캠페인 행사 종료일',
  `EVENT_STR_DATE` datetime DEFAULT NULL COMMENT '신청 기간 시작일',
  `EVENT_END_DATE` datetime DEFAULT NULL COMMENT '신청 기간 종료일',
  `TIME_SEGMENT` varchar(10) DEFAULT NULL COMMENT '주간/야간 체크',
  `ROLE` varchar(10) DEFAULT NULL COMMENT '사용자 역할',
  `LATE_YN` varchar(2) DEFAULT 'N' COMMENT '지각 여부 (Y/N)',
  `IS_LEADER` varchar(2) DEFAULT 'N' COMMENT '리더 여부 (Y/N)',
  `IS_DELETED` varchar(2) DEFAULT 'N' COMMENT '삭제 여부 (Y/N)',
  `APPLY_DATE` datetime DEFAULT NULL COMMENT '신청 날짜',
  `CREATED_AT` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '생성 일시',
  `UPDATED_AT` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정 일시',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='사용자 캠페인 참여 정보 테이블';
